import urllib.request
import urllib.error
import time

class RateLimitError(Exception):
    pass

class ServerError(Exception):
    pass

class ClientError(Exception):
    pass

class ConnectionError(Exception):
    pass

class APIClient:
    def __init__(self, base_url, timeout=10):
        self.base_url = base_url
        self.timeout = timeout

    def get(self, path):
        url = self.base_url + path
        # Try up to 3 times for rate limit (429)
        # For 5xx and network errors, retry once
        # For 4xx (except 429), raise immediately

        attempts = 0
        max_rate_limit_attempts = 3
        max_other_attempts = 2  # 1 initial + 1 retry

        while True:
            try:
                req = urllib.request.Request(url)
                response = urllib.request.urlopen(req, timeout=self.timeout)
                # Read the response body
                body = response.read().decode('utf-8')
                return body
            except urllib.error.HTTPError as e:
                code = e.code
                if code == 429:
                    # Rate limit - retry up to 3 times with exponential backoff
                    if attempts < max_rate_limit_attempts:
                        wait_time = 0.5 * (2 ** attempts)
                        time.sleep(wait_time)
                        attempts += 1
                        continue
                    else:
                        raise RateLimitError(f"Rate limited after {max_rate_limit_attempts} retries")
                elif 500 <= code <= 599:
                    # Server error - retry once after 1s
                    if attempts < max_other_attempts:
                        time.sleep(1)
                        attempts += 1
                        continue
                    else:
                        raise ServerError(f"Server error {code} after retry")
                elif 400 <= code <= 499:
                    # Client error - raise immediately
                    raise ClientError(f"Client error {code}")
                else:
                    # Other HTTP errors - raise as is
                    raise
            except urllib.error.URLError as e:
                # Network error - retry once after 1s
                if attempts < max_other_attempts:
                    time.sleep(1)
                    attempts += 1
                    continue
                else:
                    raise ConnectionError(f"Connection error after retry: {e}")
            except Exception as e:
                # Other unexpected errors
                raise
